package com.ecole.gestion_scolaire.teacherportal.entity;
import com.ecole.gestion_scolaire.hr.entity.*; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="teacher_evaluation") public class TeacherEvaluation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teacher_id") private Teacher teacher; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teaching_assignment_id") private TeachingAssignment assignment; @Column(nullable=false,length=200) private String title; private LocalDate evaluationDate; private BigDecimal maxScore; private BigDecimal coefficient=BigDecimal.ONE; @Column(columnDefinition="text") private String description; @Column(nullable=false,length=30) private String status="DRAFT"; private OffsetDateTime createdAt; private OffsetDateTime updatedAt; @PrePersist void pre(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Long getId(){return id;} public Teacher getTeacher(){return teacher;} public void setTeacher(Teacher v){teacher=v;} public TeachingAssignment getAssignment(){return assignment;} public void setAssignment(TeachingAssignment v){assignment=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public LocalDate getEvaluationDate(){return evaluationDate;} public void setEvaluationDate(LocalDate v){evaluationDate=v;} public BigDecimal getMaxScore(){return maxScore;} public void setMaxScore(BigDecimal v){maxScore=v;} public BigDecimal getCoefficient(){return coefficient;} public void setCoefficient(BigDecimal v){coefficient=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
